#include <iostream>
#include <string>
#include <vector>
#include <iterator>

int main() {
    // Initialize vector directly from standard input (cin)
    // Reads strings until EOF or non-string input causes failure.
    std::vector<std::string> coll(
        (std::istream_iterator<std::string>(std::cin)),
        (std::istream_iterator<std::string>()));

    // coll now contains all words read from input.
    // The extra parentheses are crucial to force interpretation as expressions.
}
